}

Method.Source:
/// <summary>
/// insert record
/// </summary>
public void insert()
{
    next insert();

    //copy of the salesInvoicetmp from UsingExistingReportData()
    if(this.AVAOrigSalesInvoiceTmp && this.AVAOrigSalesInvoiceTmp != this.RecId)
    {
        //copy the markup
        AvaReportingMarkupTransTmp::copyMarkupTrans(this.TableId, this.AVAOrigSalesInvoiceTmp, this.RecId);
        //reset the isCopy flag
        AvaReportingMarkupTransTmp::resetIsCopy(this.TableId, this.RecId, this.RecId);
    }
    else
    {
        //fill the markuptrans records
        CustInvoiceTrans custInvoiceTrans = CustInvoiceTrans::findRecId(this.AVACustInvoiceTrans);
        if(custInvoiceTrans)
        {
            CustInvoiceJour custInvoiceJour =  custInvoiceTrans.custInvoiceJour();
            boolean proforma = custInvoiceJour.isProforma();
            SalesLine salesline = custInvoiceTrans.salesLine();

            if(proforma)
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, salesline, custInvoiceJour.LanguageId, proforma, custInvoiceTrans.Qty, custInvoiceTrans.LineAmount, 0.0, salesline.inclTax());
            }
            else
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, custInvoiceTrans, custInvoiceJour.LanguageId);
            }
        }
    }

    this.AVAOrigSalesInvoiceTmp = this.RecId;
    this.doUpdate();
}
